import {formatLap,signed} from './engine.mjs';
const sources=[
 ['FIA / REGULATION','2024 Formula 1 Technical Regulations','https://api.fia.com/sites/default/files/fia_2024_formula_1_technical_regulations_-_issue_6_-_2024-04-30.pdf','Minimum mass, eight forward gears and hybrid constraints. The ES→K, K→ES and MGU-H energy paths must be distinguished.'],
 ['FIA / ENERGY DIAGRAM','2024 Technical Regulations — energy flow','https://www.fia.com/sites/default/files/fia_2024_formula_1_technical_regulations_-_issue_1_-_2023-04-25.pdf','Article 5.3.2 and the energy-flow diagram: ±120 kW K power, 4 MJ ES→K, 2 MJ K→ES, 4 MJ usable ES swing. MGU-H is omitted here.'],
 ['OPENF1 / OBSERVATIONS','Public historical timing & telemetry API','https://openf1.org/docs/','Sampled speed, throttle, gear, RPM, DRS, approximate position, lap/sector timing, stints and weather. Brake is binary, not measured pressure.'],
 ['FASTF1 / METHODS','FastF1 telemetry and circuit examples','https://docs.fastf1.dev/','Public telemetry handling, distance interpolation and circuit annotation methods. This build retrieves data through OpenF1; it does not claim to run FastF1 in the browser.'],
 ['PIRELLI / TYRE ALLOCATION','Opening 2024 compound nominations','https://press.pirelli.com/pirelli-nominates-the-compounds-for-the-start-of-2024/','Bahrain uses C1/C2/C3. Soft, medium and hard are event-relative labels. Allocation is observed; numerical grip curves are not public.'],
 ['PIRELLI / CIRCUIT DEMAND','The hardest compounds for Silverstone','https://press.pirelli.com/the-hardest-compounds-for-the-cradle-of-formula-1/','Fast linked corners and large lateral tyre loads inform the circuit demand classification. The numerical wear multiplier remains an assumption.'],
 ['PIRELLI / CIRCUIT DEMAND','The Monaco wheel spins round to 70','https://press.pirelli.com/the-monaco-wheel-spins-round-to-70/','2024 C3/C4/C5 allocation, smooth asphalt and comparatively low tyre energy. No universal driver wet-weather score follows from this.'],
 ['PIRELLI / 2024 ALLOCATION','All compounds on track over the next three races','https://press.pirelli.com/all-compounds-on-track-over-next-three-races/','2024 Hungary, Netherlands and Monza compound choices. The Monza C3/C4/C5 allocation is used in the circuit database.'],
 ['MERCEDES / PUBLISHED SPECIFICATION','The 2024 W15','https://www.mercedesamgf1.com/cars/2024','Corroborates 798 kg, eight forward gears and regulatory ERS/engine limits. No exact proprietary power or drag figure is inferred as fact.'],
 ['MERCEDES / ENGINEERING','Downforce in Formula One, explained','https://www.mercedesamgf1.com/news/feature-downforce-in-formula-one-explained','Aero load/drag trade-offs and airflow effects. Historical order-of-magnitude examples help check assumptions; they are not exact 2024 aero maps.'],
 ['MERCEDES / ENGINEERING','Formula One brake systems, explained','https://www.mercedesamgf1.com/news/formula-one-brake-systems-explained','Tyre/aero braking limits, rear brake blending and migration. LapLab uses an approximate two-axle force limit, without disc-temperature dynamics.'],
 ['MERCEDES / ENGINEERING','How do you set up a Formula One car?','https://www.mercedesamgf1.com/news/how-do-you-set-up-a-formula-one-car','Track-specific compromise, aero and mechanical adjustments. Real ride-height, differential and suspension maps are outside this model.'],
 ['MERCEDES / TYRES','Temperature talk','https://www.mercedesamgf1.com/news/insight-temperature-talk','Tyre operating windows and temperature-dependent grip/degradation. The source supports the mechanism, not LapLab’s assumed response width.'],
 ['NASA / PHYSICS','The drag equation','https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/drag-equation/','Dynamic pressure, drag coefficient and reference area. LapLab uses coefficient-times-area quantities to keep the convention explicit.'],
 ['NIST / METROLOGY','CIPM-2007 moist-air density','https://www.nist.gov/system/files/documents/calibrations/CIPM-2007.pdf','Authoritative density reference. LapLab uses an ideal moist-air approximation with vapour partial pressure; it does not claim CIPM accuracy.'],
 ['PRIMARY RESEARCH / LAP SIMULATION','Brayshaw & Harrison: numerical lap simulation','https://journals.sagepub.com/doi/10.1243/095440705X11211','Quasi-steady simulation, racing-line and vehicle-model considerations. A method reference, not evidence of accuracy for this implementation.'],
 ['PRIMARY RESEARCH / TYRE MODEL','Optimal tyre management of a Formula One car','https://ifatwww.et.uni-magdeburg.de/ifac2020/media/pdfs/0335.pdf','Thermal/friction/wear coupling. Historical assumed parameters are not relabelled as measured 2024 Pirelli data.'],
 ['PRIMARY RESEARCH / HYBRID MODEL','Noronha, UFSC: a public-data 2024 F1 point-mass model','https://repositorio.ufsc.br/bitstream/handle/123456789/265790/PEMC2420-D.pdf?isAllowed=y&sequence=-1','Distance-domain forward/backward speed passes, hybrid energy and public-data calibration. Architectural support only.'],
 ['VISUAL REFERENCE / ATLAS','ATLAS waveform documentation','https://docs.atlas.mclarenapplied.com/key-functionality/analyse/viewer/displays/waveform/','The actual waveform interface informed aligned channel readouts, a quiet plot canvas and a shared cursor.'],
 ['VISUAL REFERENCE / RACESTUDIO','AiM RaceStudio 3 analysis','https://www.aim-sportline.com/docs/racestudio3/manual/html/analysis.html','The actual time-distance workspace and split report informed distance alignment and linked circuit/section inspection.'],
 ['VISUAL REFERENCE / COSWORTH','Pi Toolbox','https://www.cosworth.com/motorsport/products/pi-toolbox/','The rendered product interface informed simultaneous track and telemetry context. LapLab is an independent design.']
];
const evidenceRows=[
 ['Lap / sector timing','O','62 earlier calibration laps; 117 later matched soft-tyre laps are held out. Public feed timing is retained with source URLs.'],
 ['Circuit dimensions / turns','O / E','FIA map lengths and numbered turns. Positions use approximate OpenF1 locations and MultiViewer annotations. Distance is normalized to official lap length.'],
 ['Speed, throttle, brake-on','O','OpenF1 broadcast-derived channels at about 3.7 Hz. Brake-on is binary. No steering or brake pressure exists in this feed.'],
 ['Vehicle force balance','O / A','Newtonian acceleration and aerodynamic dynamic pressure are supported physics. Effective coefficients and load distribution remain uncertain.'],
 ['Car differences','E','Fleet-relative fits from matched early soft laps alter grip, drag, effective power, braking and traction. These coefficients are not proprietary car specifications.'],
 ['Driver differences','E','Original-teammate-centred speed-band, deceleration and throttle-pickup residuals, shrunk toward the mean. This is a session-limited proxy, confounded by car/setup/conditions.'],
 ['Tyre compound / age','O / A','C-number allocation and stint ages are observed. Off-soft grip and wear response coefficients are assumed; they were not fitted to fuel-corrected race stints.'],
 ['Track temperature','A','A stationary effective-grip response centred on recorded conditions. Track temperature is not tyre temperature. No transient carcass/tread model is claimed.'],
 ['Air / humidity / pressure','O / A','Session weather anchors are observed; the moist ideal-gas density equation is approximate. Engine cooling and turbo-control responses are omitted.'],
 ['Wind','A','A vector changes relative airflow per segment. Direction is relative to finish-straight heading. Constant wind, no gust/yaw map; recorded wind is absorbed by baseline calibration.'],
 ['Aero trim / brake bias','A','Each trim step changes assumed downforce area by 2% and drag area by 1.5%. Brake bias uses approximate axle normal loads, CoG height and wheelbase.'],
 ['ERS / DRS','O / A','FIA limits and mapped DRS zones constrain an ES-only deployment abstraction. Strategy, conversion loss and DRS whole-car drag reduction are assumed.'],
 ['Traffic / rain / risk','A','Exploratory wake/tow, water proxy and grip-utilization margins. Not empirically validated, with wider heuristic envelopes. No crash probability or aquaplaning model.'],
];
const tag=kind=>`<span class="evidence ${kind==='O'?'observed':kind==='E'?'estimate':'assumption'}">${kind}</span>`;
export function researchHTML(db){
 const errors=db.holdout.map(x=>Math.abs(x.error)),mae=errors.reduce((a,b)=>a+b,0)/errors.length,bias=db.holdout.reduce((a,b)=>a+b.error,0)/errors.length;
 return `<section id="method" class="panel research-block"><p class="eyebrow">01 / THE SIMULATION ENGINE</p><h2>A lap is a speed profile, not a sum of arbitrary penalties.</h2><div class="research-grid"><div><p>The model moves around the circuit in 600 distance intervals. A telemetry-derived corner envelope sets lateral limits. Backward passes constrain braking into those corners; forward passes constrain power and traction on the way out. Eight periodic passes couple the start and finish of a flying lap.</p><div class="formula">F<sub>drag</sub> = ½ ρ (C<sub>D</sub>·A) |v<sub>air</sub>| (v<sub>air</sub>·t)<br>F<sub>down</sub> = ½ ρ (C<sub>L</sub>·A) |v<sub>air</sub>|²<br>m v² κ ≤ tyre lateral force capacity<br>v<sub>next</sub>² = v² + 2 a Δs &nbsp; · &nbsp; Δt = 2 Δs / (v + v<sub>next</sub>)</div><ol class="method-list"><li><b>01</b><span>Normalize sampled speed and approximate map positions to the FIA circuit length. Infer an <em>effective</em> corner curvature from the median early-lap speed envelope; this is not a surveyed radius.</span></li><li><b>02</b><span>Calculate mass, moist-air density, relative wind, drag, downforce and a load-sensitive tyre capacity. A friction ellipse shares capacity between turning and longitudinal forces.</span></li><li><b>03</b><span>Apply modest car fits and original-teammate driver residuals to specific grip, braking, power and traction capacities. The lap is never multiplied by a team or driver rating afterwards.</span></li><li><b>04</b><span>Run braking/acceleration passes, integrate sector and corner-section time, and account for energy with simulated time. A soft empirical speed ceiling at 1.18× reference is a disclosed stability bound.</span></li><li><b>05</b><span>Animate the exact solver distance s(t). Replay, chart hover and the slider all use the same result arrays. Gear/RPM and brake effort are generated approximations.</span></li></ol><p>Per-circuit drag and effective-curvature multipliers are fitted to the median training speed maximum and mean training lap time. No later held-out timing is used in those fits. The shared aero/tyre priors remain unidentifiable from public data.</p></div><aside class="parameter-card"><h3>Current model quantities</h3><p>Read these as effective coefficients, not engineering specifications of the selected car.</p><div id="current-parameters"></div><h3>Declared priors ${tag('A')}</h3><p>μ reference 1.55; nominal CL·A 6.8 m² before circuit trim; nominal CD·A 1.08 m² before fit. Tyre-load exponent 0.92; rolling coefficient 0.012; CoG height 0.30 m; wheelbase 3.6 m; 45/55% static axle load and 50/50% aero load. These are explicit assumptions checked against multiple public laps.</p><p>Nominal wheel power is inferred from high-throttle straight acceleration with an assumed drag area. A 90 kW reference electrical component is subtracted to estimate the effective ICE component. Power/drag cannot be uniquely separated here.</p></aside></div></section>
 <section id="evidence" class="panel research-block"><p class="eyebrow">02 / EVIDENCE REGISTER</p><h2>Measured, estimated, assumed.</h2><p>${tag('O')} Observed or regulated &nbsp;&nbsp; ${tag('E')} Estimated / calibrated &nbsp;&nbsp; ${tag('A')} Assumed / approximated. A sound physical equation does not make its unknown inputs certain.</p><div class="table-scroll"><table class="evidence-table"><thead><tr><th>Factor</th><th>Evidence</th><th>How it enters the model / limit</th></tr></thead><tbody>${evidenceRows.map(([name,kind,body])=>`<tr><td>${name}</td><td>${kind.split(' / ').map(tag).join(' ')}</td><td>${body}</td></tr>`).join('')}</tbody></table></div><details><summary>Tyre response coefficients and circuit demand</summary><p>Soft/medium/hard grip multipliers: 1.000 / 0.975 / 0.949. Age slopes per lap: 0.0025 / 0.00155 / 0.001, scaled by circuit demand. Thermal grip correction: 1 − 0.00016 × (track temperature − reference)², bounded for stability. The demand ordering is informed by Pirelli; numerical demand factors (Silverstone 1.12, Monza 0.70, Monaco 0.48, Bahrain 1.20) and curve coefficients are assumed. Effective tyre state is stationary over this single flying lap. No measured tyre temperature, pressure or degradation curve is fabricated.</p></details><details><summary>Energy limits, active aero and gearing</summary><p>MGU-K output is bounded at 120 kW; ES→K usage at 4 MJ/lap, K→ES recovery at 2 MJ/lap and store charge at 4 MJ. The store starts full for the experiment. MGU-H pathways are excluded, so this is a conservative ES-only abstraction, not the full 2024 energy system. No 2026 active-aero or power-unit behaviour is represented.</p><p>DRS uses recorded active stretches inside the FIA-verified zone layout, closes during model braking, and is disabled in wet experiments. Assumed whole-car drag/downforce changes are −20% / −12%. Race mode requires the user to model a following gap ≤1 s; actual race-control enablement and eligibility timing are not simulated. Gear follows a generic speed-threshold schedule; RPM/speed ratios are estimated from sampled gear data. There is no proprietary gear-ratio or torque-map model.</p></details><details><summary>Driver and car estimation method</summary><p>Training traces are aligned by normalized lap distance. Low-/high-speed corner retention, straight speed, inferred wheel power, upper-quantile deceleration and throttle pickup are compared within the original teammates. Driver residuals are shrunk 40% for speed bands and 25% for braking/pickup; car fits are modest fleet-relative residuals. These shrinkage strengths are modeling choices. No stable personality, kerb-use, trail-brake-pressure, steering-smoothness or wet-strength score is claimed.</p><p>Driver transplant experiments keep that limited original-team residual, and receive a wider assumed envelope. Pérez has no matched soft-tyre Silverstone training data; that circuit is excluded from his fingerprint.</p></details><details><summary>Factors deferred until supporting data and dynamics exist</summary><p>Real ride height / ground-effect height maps, differential and wheel slip, suspension / camber / toe, detailed brake temperature, surveyed elevation and banking, kerb contact, lateral racing-line optimization, damage, tyre pressure, transient tyre thermal history, aquaplaning, cooling derates, gearshift losses and track-limit legality. OpenF1 z is not treated as a survey-quality elevation profile. Track limits and flag deletions were not comprehensively filtered in this snapshot; this affects calibration and validation quality.</p></details></section>
 <section id="validation" class="panel research-block"><p class="eyebrow">03 / HISTORICAL VALIDATION</p><h2>Real laps. Visible errors.</h2><p>The first two eligible soft flying laps per driver/circuit enter calibration; later eligible soft laps form the chronological holdout. Eligibility requires full timed sectors, no pit-out flag and a lap within 3.5% of that driver’s session-best timed lap. This quality threshold uses session outcomes, so it is not a fully blind sampling protocol. Held-out values do not enter parameter estimation.</p><div class="validation-summary"><div><span>CALIBRATION LAPS</span><b>${db.training.length}</b></div><div><span>HELD-OUT LAPS</span><b>${db.holdout.length}</b></div><div><span>MEAN ABSOLUTE ERROR</span><b>${mae.toFixed(2)} s</b></div><div><span>SIGNED BIAS · PRED − ACTUAL</span><b>+${bias.toFixed(2)} s</b></div></div><p>The positive bias is visible: earlier laps anchor a slower envelope than later qualifying runs. Fuel (10 kg) and initial battery state are unknown assumptions. Known held-out weather and stint age are inputs; setup, track evolution, lap deletions and flag effects remain confounded. This validates a limited qualifying reference domain, not wet conditions, other compounds, traffic or every slider. Sector predictions are also retained in the downloadable dataset.</p><div class="validation-controls"><label for="validation-filter">Circuit</label><select id="validation-filter"><option value="all">All four circuits</option>${db.circuits.map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select><button class="button quiet" id="export-validation">Export validation CSV ↓</button></div><div class="validation-table"><table><thead><tr><th>Sample / held out</th><th>Predicted</th><th>Actual</th><th>Error</th><th>Source</th></tr></thead><tbody id="validation-rows"></tbody></table></div><p id="validation-count" class="small-note"></p><h3>Snapshot and API recovery</h3><p>Retrieved 7 October 2026. Simulation uses the bundled historical snapshot and runs locally; it never depends on a live timing service. This check verifies stored timing samples and preserves the fitted snapshot when the API is unavailable, rate-limited, malformed or changed.</p><div class="load-data"><button id="verify-feed" class="button quiet">Verify current circuit against OpenF1 ↗</button><a class="button quiet" href="./data/dataset.json" download="laplab-research-dataset.json">Download dataset ↓</a></div><p id="feed-status" class="small-note">Bundled public-data snapshot available. No live API request made.</p></section>
 <section id="circuits" class="panel research-block"><p class="eyebrow">04 / CIRCUIT DATABASE</p><h2>The circuit changes the problem.</h2><div class="table-scroll"><table class="evidence-table"><thead><tr><th>Circuit</th><th>FIA layout</th><th>Modeled context and surface evidence</th></tr></thead><tbody>${db.circuits.map(c=>`<tr><td>${c.name}<br>${c.length.toLocaleString()} m · ${c.turns} turns</td><td><a href="${c.mapSource}" target="_blank" rel="noopener noreferrer">FIA 2024 map ↗</a><br><a href="${c.annotationSource}" target="_blank" rel="noopener noreferrer">Turn annotations ↗</a></td><td>${c.description} ${c.surface} Geometry, reference speed demands, DRS-active stretches, corner and sector regions affect the solver. Elevation and camber dynamics are deferred.</td></tr>`).join('')}</tbody></table></div></section>
 <section id="sources" class="panel research-block"><p class="eyebrow">05 / SOURCE LIBRARY</p><h2>Follow the evidence.</h2><p>Primary regulations, supplier information, engineering explanations, public data and method papers. Each supports a specific mechanism or boundary; none provides a complete proprietary F1 vehicle model.</p><ul class="source-list">${sources.map(([category,title,url,description])=>`<li><span>${category}</span><a href="${url}" target="_blank" rel="noopener noreferrer">${title} ↗</a><p>${description}</p></li>`).join('')}</ul><h3>Attribution and data use</h3><p>OpenF1 is independent and provides public historical data under CC BY-NC-SA 4.0 for non-commercial research. MultiViewer supplies public circuit annotations, checked against FIA maps; annotations are estimates. IBM Plex fonts use the SIL Open Font License. F1 LapLab is not an official timing, regulation, team or tyre-supplier product.</p></section>`;
}
export function renderValidation(db,filter='all'){
 const rows=db.holdout.filter(r=>filter==='all'||r.circuit===filter);
 document.querySelector('#validation-rows').innerHTML=rows.map(r=>{const d=db.drivers.find(d=>d.id===r.driver),c=db.circuits.find(c=>c.id===r.circuit);return `<tr><td>${c.name} / ${d.code} / L${r.lap}</td><td>${formatLap(r.predicted)}</td><td>${formatLap(r.actual)}</td><td class="${r.error>0?'loss':'gain'}">${signed(r.error)} s</td><td><a href="${r.source}" target="_blank" rel="noopener noreferrer">OpenF1 ↗</a></td></tr>`;}).join('');
 document.querySelector('#validation-count').textContent=`Showing ${rows.length} held-out samples. All errors are calculated as prediction minus actual; none of these laps was used for fitting.`;
}
